#
# t_phase3_equilibrium.jl
#
# To compare the equilibrium Green's functions with NESSi, point by point.
# The data are generated by .nessi/kbref/p3_equilibrium_ref.cpp, whose
# closed-form inputs are rebuilt here with exactly the same formulas
# (nothing is read back from the output).
#
# NESSi reference: libcntr/cntr/cntr_equilibrium_impl.hpp:25-1559.
#
# Tolerance groups:
#   * direct formulas (constant/time-dependent H, single pole XX):
#     atol = rtol = 1e-12;
#   * adaptive DOS integrals (Bethe, custom DOS): primary gate
#     atol = rtol = 1e-10. The aggregate norm ≤ 1e-9 is an additional
#     diagnostic of the accumulated round-off of the multi-panel sums only,
#     it does not replace the primary gate.
#

using LinearAlgebra

isdefined(@__MODULE__, :P3_DATA) ||
    (const P3_DATA = joinpath(@__DIR__, "..", "..", "data", "test", "phase3"))

function eq_case(name, d, sign)
    ref = read_kbref(joinpath(P3_DATA, name * ".dat"))
    @test ref.metadata["case"] == name
    @test parse(Int, ref.metadata["sig"]) == sign
    nt = parse(Int, ref.metadata["nt"])
    ntau = parse(Int, ref.metadata["ntau"])
    β = parse(Float64, ref.metadata["beta"])
    h = parse(Float64, ref.metadata["h"])
    μ = parse(Float64, ref.metadata["mu"])
    C = Cn(nt + 1, ntau + 1, d, d, nt * h, β)
    return ref, ℱ(C, sign), β, h, μ
end

# Sum of all point-wise errors
function eq_aggregate(G::ℱ, ref)
    return sum(abs(kb_value(G, row) - row.value) for row in ref.rows)
end

function eq_report(name, errs)
    @printf("  %-28s max err: mat %.2e ret %.2e tv %.2e les %.2e\n",
            name, errs["mat"], errs["ret"], errs["tv"], errs["les"])
end

@testset verbose = true "NESSi: phase 3 equilibrium" begin
    @testset "constant Hamiltonian" begin
        H1 = fill(C64(0.4), 1, 1)
        H2 = C64[-0.3 0.4-0.2im; 0.4+0.2im 0.6]
        for (s, sign) in (("fermion", FERMI), ("boson", BOSE)), (dn, H0) in (("1x1", H1), ("2x2", H2))
            name = "green_const_$(s)_$(dn)"
            ref, G, β, h, μ = eq_case(name, size(H0, 1), sign)
            @test μ == (sign == FERMI ? 0.1 : -1.0)
            from_ham!(G, μ, H0, β, h)
            eq_report(name, test_kbref(G, ref; atol = 1e-12, rtol = 1e-12))
        end
    end

    @testset "time-dependent Hamiltonian" begin
        for (name, sign, cf) in (("green_time_cf2_fermion", FERMI, 2),
                                 ("green_time_cf4_fermion", FERMI, 4),
                                 ("green_time_cf4_boson", BOSE, 4))
            ref, G, β, h, μ = eq_case(name, 2, sign)
            @test ref.metadata["method"] == "cf$cf"
            nt = getntime(G) - 1
            H = Cf(nt + 1, 2, 2)
            H[0] = C64[1.0 0.5; 0.5 -1.0]
            for n = 0:nt
                t = n * h
                H[n+1] = C64[1.0 0.5*exp(-1.4im*t); 0.5*exp(1.4im*t) -1.0]
            end
            from_ham!(G, μ, H, β, h; fix_hamiltonian = true, solve_order = 5,
                          cf_order = cf)
            eq_report(name, test_kbref(G, ref; atol = 1e-12, rtol = 1e-12))
        end
    end

    @testset "DOS" begin
        # Bethe lattice, Matsubara component only
        ref, G, β, h, μ = eq_case("green_bethe_mat_fermion", 2, FERMI)
        from_dos_mat_bethe!(G, β; μ = μ)
        eq_report("green_bethe_mat_fermion", test_kbref(G, ref; atol = 1e-10, rtol = 1e-10))
        @test eq_aggregate(G, ref) ≤ 1e-9
        #
        # Bethe lattice, all components
        ref, G, β, h, μ = eq_case("green_bethe_full_fermion", 2, FERMI)
        from_dos_bethe!(G, β, h; μ = μ)
        eq_report("green_bethe_full_fermion", test_kbref(G, ref; atol = 1e-10, rtol = 1e-10))
        @test eq_aggregate(G, ref) ≤ 1e-9
        #
        # Smooth DOS with finite support
        ref, G, β, h, μ = eq_case("green_custom_dos_fermion", 1, FERMI)
        dos(x) = (y = 1.0 - x * x; y < 0.0 ? 0.0 : 15.0 / 16.0 * y * y)
        from_dos!(G, dos, -1.0, 1.0, β, h; μ = μ, limit = 60, nn = 24)
        eq_report("green_custom_dos_fermion", test_kbref(G, ref; atol = 1e-10, rtol = 1e-10))
        @test eq_aggregate(G, ref) ≤ 1e-9
    end

    @testset "single pole XX" begin
        ref, D, β, h, _ = eq_case("green_single_pole", 1, BOSE)
        green_single_pole!(D, 1.4, β, h)
        eq_report("green_single_pole", test_kbref(D, ref; atol = 1e-12, rtol = 1e-12))
    end
end
